<?phpfunction shw_post_thumbnail_default(): string {	$thumb_logo = SHW_URL . '/assets/images/blog/16by9/small/04.jpg';	return "<img  class='img-thumbnail'  src='" . esc_url($thumb_logo) . "' alt='image'>";}function shw_post_thumbnail(): string {	if (has_post_thumbnail()){	  return get_the_post_thumbnail('','full',			[				'class'=>'img-responsive card-img',				'alt'=>get_the_title()		]);	} else{	 return	shw_post_thumbnail_default() ;	}}function shw_post_thumbnail_url(): string {	if (has_post_thumbnail()){		return get_the_post_thumbnail_url();	}else {        return SHW_URL . '/assets/images/blog/16by9/small/04.jpg';    }}